window.AUTH=window.AUTH||{};window.AUTH["23-583"]={"d":"23-583","id":"2024/23-583","n":"Bouarfa v. Mayorkas","briefs":[{"k":"petitioner","label":"Brief of petitioner Amina Bouarfa","date":"2024-07-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-583/316333/20240703131612074_2024-07-03%20Bouarfa%20No.%2023-583%20Merits%20Brief%20with%20addendum.pdf","side":"pet","n":83},{"k":"respondent","label":"Brief of respondents Alejandro Mayorkas, Secretary of Homeland Security, et al.","date":"2024-08-22","url":"https://www.supremecourt.gov/DocketPDF/23/23-583/323179/20240822153442714_23-583bsUnitedStates.pdf","side":"res","n":72},{"k":"reply","label":"Reply of petitioner Amina Bouarfa","date":"2024-09-23","url":"https://www.supremecourt.gov/DocketPDF/23/23-583/326644/20240923152602690_2024-09-23%20Bouarfa%20No.%2023-583%20Reply%20Brief.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r03_3f14.pdf","tr":true,"items":[{"t":"case","label":"Ayanbadejo v. Chertoff","cite":"517 F.3d 273","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/517/273/","by":{"0":"26"}},{"t":"case","label":"Bernal-Vallejo v. INS","cite":"195 F.3d 56","y":1999,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/195/56/","by":{"0":"33"}},{"t":"case","label":"Billeke-Tolosa v. Ashcroft","cite":"385 F.3d 708","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/385/708/","by":{"0":"33"}},{"t":"case","label":"Boukhris v. Perryman","cite":"2002 WL 193354","y":2002,"court":"N.D. Ill. Feb. 7","by":{"0":"14"}},{"t":"case","label":"Campos-Chaves v. Garland","cite":"144 S. Ct. 1637","y":2024,"id":"2023/22-674","sc":1,"ar":1,"sum":"Because each of the aliens in this case received a proper notice for the removal hearings they missed and at which they were ordered removed from the United States, see 8 U. S. C. §1229(a)(2), they cannot seek rescission of their in absentia removal orders on the basis of defective notice under §1229a(b)(5)(C)(ii).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"Cho v. Gonzales","cite":"404 F.3d 96","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/404/96/","by":{"0":"25, 34"}},{"t":"case","label":"Corner Post Inc. v. Board of Governors of Federal Reserve Bank","cite":"603 U.S. ___","y":2024,"id":"2023/22-1008","sc":1,"sum":"An Administrative Procedures Act claim does not accrue for purposes of 28 U. S. C. §2401(a)—the default 6-year statute of limitations applicable to suits against the United States—until the plaintiff is injured by final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22"}},{"t":"case","label":"De Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Department of Homeland Security v. Regents of the University of California","cite":"591 U.S. 1","y":2020,"id":"2019/18-587","sc":1,"op":6,"ar":2,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Ghaly v. INS","cite":"48 F.3d 1426","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/48/1426/","by":{"0":"2, 7, 28"}},{"t":"case","label":"Ginters v. Frazier","cite":"614 F.3d 822","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/822/","by":{"0":"12, 26"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"589 U.S. 221","y":2020,"id":"2019/18-776","sc":1,"op":3,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"17, 23, 33, 37","1":"29, 32","2":"4"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Hernandez v. Ashcroft","cite":"345 F.3d 824","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/345/824/","by":{"0":"33"}},{"t":"case","label":"Ikenokwalu-White v. INS","cite":"316 F.3d 798","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/316/798/","by":{"0":"33"}},{"t":"case","label":"INS v. Bagamasbad","cite":"429 U.S. 24","y":1976,"id":"1976/75-1666","sc":1,"sum":"Where respondent alien, upon overstaying her tourist visa, applied to have her status adjusted to that of a permanent resident alien pursuant to 8 U. S. C. § 1255 (a) (which authorizes the Attorney General in his discretion to make such an adjustment if, inter alia, the alien would be eligible for an immigrant visa and admissible as a permanent resident), an immigration judge in denying the application in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10","2":"17"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"19, 20, 32, 37","1":"30","2":"11"}},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"sum":"The Attorney General has properly exercised his discretionary powers under the statute in this case, and denial of the application is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"10, 11, 12"}},{"t":"case","label":"Jomaa v. United States","cite":"940 F.3d 291","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/940/291/","op":1,"by":{"0":"17, 26, 46"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"op":3,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"10, 11, 24, 25, 30, 39","1":"25","2":"10, 16, 17, 19"}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 38","2":"3, 13"}},{"t":"case","label":"Page(s) Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"0":"22","2":"12"}},{"t":"case","label":"Marquez-Perez v. Rardin","cite":"221 F.3d 1139","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/221/1139/","by":{"0":"33"}},{"t":"case","label":"Maslenjak v. United States","cite":"582 U.S. 335","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"0":"4, 5, 20, 37, 38, 39","1":"37, 38","2":"21"}},{"t":"case","label":"McNary v. Haitian Refugee Center, Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"sum":"The District Court had federal-question jurisdiction to hear respondents' constitutional and statutory challenges to the INS procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","1":"34, 35"}},{"t":"case","label":"Mejia Rodriguez v. United States DHS","cite":"562 F.3d 1137","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/562/1137/","by":{"0":"50, 51"}},{"t":"case","label":"Mendoza v. Secretary, DHS","cite":"851 F.3d 1348","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/851/1348/","op":1,"by":{"0":"27","1":"4"}},{"t":"case","label":"Mestanek v. Jaddou","cite":"93 F.4th 164","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/164/","by":{"0":"27"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"5, 42"}},{"t":"case","label":"Ogbolumani v. Napolitano","cite":"557 F.3d 729","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/557/729/","by":{"0":"26"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"op":9,"ar":2,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"12, 25, 34, 41, 48-51","1":"15, 27-29, 31-35","2":"16, 17, 18"}},{"t":"case","label":"Perez Perez v. Wolf","cite":"943 F.3d 853","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/853/","sum":"Holding that U visa petition determinations are not “‘wholly discretionary’” (citation omitted).","sumSrc":"brief:0","by":{"0":"36"}},{"t":"case","label":"Privett v. Secretary, DHS","cite":"865 F.3d 375","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/375/","by":{"0":"43"}},{"t":"case","label":"Ruiz v. Mukasey","cite":"552 F.3d 269","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/552/269/","op":1,"by":{"0":"25, 26"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Salinas v. United States Railroad Retirement Board","cite":"592 U.S. 188","y":2021,"id":"2020/19-199","sc":1,"sum":"The U. S. Railroad Retirement Board’s denial of a request to reopen a prior benefits determination under the Railroad Retirement Act of 1974 and the Railroad Unemployment Insurance Act is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"3, 23"}},{"t":"case","label":"Shalala v. Illinois Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"41"}},{"t":"case","label":"Soto v. United States Department of State","cite":"2016 WL 3390667","y":2016,"court":"D.D.C. June 17","by":{"0":"43"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"42, 43"}},{"t":"case","label":"United States ex rel. Accardi v. Shaughnessy","cite":"347 U.S. 260","y":1954,"id":"1940-1955/347us260","sc":1,"sum":"Petitioner is entitled to an opportunity in thp district court to prove the allegation; and, if he does prove it, he should receive a new hearing before the Board without the burden of previous proscription by the list.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Wilkinson v. Garland","cite":"601 U.S. 209","y":2024,"id":"2023/22-666","sc":1,"sum":"The Immigration Judge’s discretionary decision that Mr. Wilkinson failed to satisfy 8 U. S. C. §1229b(b)(1)(D)’s “exceptional and extremely unusual” hardship standard for determining eligibility for cancellation of removal is a mixed question of law and fact, reviewable under §1252(a)(2)(D)’s jurisdiction restoring exception for “questions of law”; the Third Circuit’s holding that the IJ’s decision was unreviewable under §1252(a)(2)(B)(i) was in error.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 25","1":"18, 19, 29, 32","2":"11, 18"}},{"t":"case","label":"Page(s) Yohannes v. Holder","cite":"585 F.3d 402","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/585/402/","sum":"Holding that “[a]lthough the ultimate decision whether to grant [a hardship] waiver” under 8 U.S.C. § 1186a(c)(4) “is discretionary” and unreviewable under clause (ii), the court had “jurisdiction to consider the legal standard for a good faith marriage and to determine whether the credited evidence meets that standard”.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"0":"10"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"10"}},{"t":"usc","label":"8 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/8/1151","subs":["(b)(2)(A)(i)"],"stext":{"head":"§1151. Worldwide level of immigration","paras":[[0,"(a) In general"],[0,"Exclusive of aliens described in subsection (b), aliens born in a foreign state or dependent area who may be issued immigrant visas or who may otherwise acquire the status of an alien lawfully admitted to the United States for permanent residence are limited to—"],[1,"(1) family-sponsored immigrants described in section 1153(a) of this title (or who are admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent under section 1153(a) of this title) in a number not to exceed in any fiscal year the number specified in subsection (c) for that year, and not to exceed in any of the first 3 quarters of any fiscal year 27 percent of the worldwide level under such subsection for all of such fiscal year;"],[1,"(2) employment-based immigrants described in section 1153(b) of this title (or who are admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent under section 1153(b) of this title), in a number not to exceed in any fiscal year the number specified in subsection (d) for that year, and not to exceed in any of the first 3 quarters of any fiscal year 27 percent of the worldwide level under such subsection for all of such fiscal year; and"],[1,"(3) for fiscal years beginning with fiscal year 1995, diversity immigrants described in section 1153(c) of this title (or who are admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent under section 1153(c) of this title) in a number not to exceed in any fiscal year the number specified in subsection (e) for that year, and not to exceed in any of the first 3 quarters of any fiscal year 27 percent of the worldwide level under such subsection for all of such fiscal year."],[0,"(b) Aliens not subject to direct numerical limitations"],[0,"Aliens described in this subsection, who are not subject to the worldwide levels or numerical limitations of subsection (a), are as follows:"],[1,"(1)(A) Special immigrants described in subparagraph (A) or (B) of section 1101(a)(27) of this title."],[1,"(B) Aliens who are admitted under section 1157 of this title or whose status is adjusted under section 1159 of this title."],[1,"(C) Aliens whose status is adjusted to permanent residence under section 1160 or 1255a of this title."],[1,"(D) Aliens whose removal is canceled under section 1229b(a) of this title."],[1,"(E) Aliens provided permanent resident status under section 1259 of this title."],[1,"(2)(A)(i) Immediate relatives.—For purposes of this subsection, the term \"immediate relatives\" means the children, spouses, and parents of a citizen of the United States, except that, in the case of parents, such citizens shall be at least 21 years of age. In the case of an alien who was the spouse of a citizen of the United States and was not legally separated from the citizen at the time of the citizen's death, the alien (and each child of the alien) shall be considered, for purposes of this subsection, to remain an immediate relative after the date of the citizen's death but only if the spouse files a petition under section 1154(a)(1)(A)(ii) of this title within 2 years after such date and only until the date the spouse remarries. For purposes of this clause, an alien who has filed a petition under clause (iii) or (iv) of section 1154(a)(1)(A) of this title remains an immediate relative in the event that the United States citizen spouse or parent loses United States citizenship on account of the abuse."],[1,"(ii) Aliens admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent who is such an immediate relative."],[1,"(B) Aliens born to an alien lawfully admitted for permanent residence during a temporary visit abroad."],[0,"(c) Worldwide level of family-sponsored immigrants"],[0,"(1)(A) The worldwide level of family-sponsored immigrants under this subsection for a fiscal year is, subject to subparagraph (B), equal to—"],[1,"(i) 480,000, minus"],[1,"(ii) the sum of the number computed under paragraph (2) and the number computed under paragraph (4), plus"],[1,"(iii) the number (if any) computed under paragraph (3)."],[0,"(B)(i) For each of fiscal years 1992, 1993, and 1994, 465,000 shall be substituted for 480,000 in subparagraph (A)(i)."],[0,"(ii) In no case shall the number computed under subparagraph (A) be less than 226,000."],[0,"(2) The number computed under this paragraph for a fiscal year is the sum of the number of aliens described in subparagraphs (A) and (B) of subsection (b)(2) who were issued immigrant visas or who otherwise acquired the status of aliens lawfully admitted to the United States for permanent residence in the previous fiscal year."],[0,"(3)(A) The number computed under this paragraph for fiscal year 1992 is zero."],[0,"(B) The number computed under this paragraph for fiscal year 1993 is the difference (if any) between the worldwide level established under paragraph (1) for the previous fiscal year and the number of visas issued under section 1153(a) of this title during that fiscal year."],[0,"(C) The number computed under this paragraph for a subsequent fiscal year is the difference (if any) between the maximum number of visas which may be issued under section 1153(b) of this title (relating to employment-based immigrants) during the previous fiscal year and the number of visas issued under that section during that year."],[0,"(4) The number computed under this paragraph for a fiscal year (beginning with fiscal year 1999) is the number of aliens who were paroled into the United States under section 1182(d)(5) of this title in the second preceding fiscal year—"],[1,"(A) who did not depart from the United States (without advance parole) within 365 days; and"],[1,"(B) who (i) did not acquire the status of aliens lawfully admitted to the United States for permanent residence in the two preceding fiscal years, or (ii) acquired such status in such years under a provision of law (other than subsection (b)) which exempts such adjustment from the numerical limitation on the worldwide level of immigration under this section."],[0,"(5) If any alien described in paragraph (4) (other than an alien described in paragraph (4)(B)(ii)) is subsequently admitted as an alien lawfully admitted for permanent residence, such alien shall not again be considered for purposes of paragraph (1)."],[0,"(d) Worldwide level of employment-based immigrants"],[0,"(1) The worldwide level of employment-based immigrants under this subsection for a fiscal year is equal to—"],[1,"(A) 140,000, plus"],[1,"(B) the number computed under paragraph (2)."],[0,"(2)(A) The number computed under this paragraph for fiscal year 1992 is zero."],[0,"(B) The number computed under this paragraph for fiscal year 1993 is the difference (if any) between the worldwide level established under paragraph (1) for the previous fiscal year and the number of visas issued under section 1153(b) of this title during that fiscal year."],[0,"(C) The number computed under this paragraph for a subsequent fiscal year is the difference (if any) between the maximum number of visas which may be issued under section 1153(a) of this title (relating to family-sponsored immigrants) during the previous fiscal year and the number of visas issued under that section during that year."],[0,"(e) Worldwide level of diversity immigrants"],[0,"The worldwide level of diversity immigrants is equal to 55,000 for each fiscal year."],[0,"(f) Rules for determining whether certain aliens are immediate relatives"],[0,"(1) Age on petition filing date"],[1,"Except as provided in paragraphs (2) and (3), for purposes of subsection (b)(2)(A)(i), a determination of whether an alien satisfies the age requirement in the matter preceding subparagraph (A) of section 1101(b)(1) of this title shall be made using the age of the alien on the date on which the petition is filed with the Attorney General under section 1154 of this title to classify the alien as an immediate relative under subsection (b)(2)(A)(i)."],[0,"(2) Age on parent's naturalization date"],[1,"In the case of a petition under section 1154 of this title initially filed for an alien child's classification as a family-sponsored immigrant under section 1153(a)(2)(A) of this title, based on the child's parent being lawfully admitted for permanent residence, if the petition is later converted, due to the naturalization of the parent, to a petition to classify the alien as an immediate relative under subsection (b)(2)(A)(i), the determination described in paragraph (1) shall be made using the age of the alien on the date of the parent's naturalization."],[0,"(3) Age on marriage termination date"],[1,"In the case of a petition under section 1154 of this title initially filed for an alien's classification as a family-sponsored immigrant under section 1153(a)(3) of this title, based on the alien's being a married son or daughter of a citizen, if the petition is later converted, due to the legal termination of the alien's marriage, to a petition to classify the alien as an immediate relative under subsection (b)(2)(A)(i) or as an unmarried son or daughter of a citizen under section 1153(a)(1) of this title, the determination described in paragraph (1) shall be made using the age of the alien on the date of the termination of the marriage."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1151?type=usc&year=mostrecent&link-type=html"},"head":"§1151. Worldwide level of immigration","tname":"Aliens and Nationality","by":{"0":"5","1":"14-16, 23, 14"}},{"t":"usc","label":"8 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/8/1153","subs":["(a)(2)(B)","(f)","(b)"],"stext":{"head":"§1153. Allocation of immigrant visas","paras":[[0,"(a) Preference allocation for family-sponsored immigrants"],[0,"Aliens subject to the worldwide level specified in section 1151(c) of this title for family-sponsored immigrants shall be allotted visas as follows:"],[0,"(1) Unmarried sons and daughters of citizens"],[1,"Qualified immigrants who are the unmarried sons or daughters of citizens of the United States shall be allocated visas in a number not to exceed 23,400, plus any visas not required for the class specified in paragraph (4)."],[0,"(2) Spouses and unmarried sons and unmarried daughters of permanent resident aliens"],[1,"Qualified immigrants—"],[2,"(A) who are the spouses or children of an alien lawfully admitted for permanent residence, or"],[2,"(B) who are the unmarried sons or unmarried daughters (but are not the children) of an alien lawfully admitted for permanent residence,"],[1,"shall be allocated visas in a number not to exceed 114,200, plus the number (if any) by which such worldwide level exceeds 226,000, plus any visas not required for the class specified in paragraph (1); except that not less than 77 percent of such visa numbers shall be allocated to aliens described in subparagraph (A)."],[0,"(3) Married sons and married daughters of citizens"],[1,"Qualified immigrants who are the married sons or married daughters of citizens of the United States shall be allocated visas in a number not to exceed 23,400, plus any visas not required for the classes specified in paragraphs (1) and (2)."],[0,"(4) Brothers and sisters of citizens"],[1,"Qualified immigrants who are the brothers or sisters of citizens of the United States, if such citizens are at least 21 years of age, shall be allocated visas in a number not to exceed 65,000, plus any visas not required for the classes specified in paragraphs (1) through (3)."],[0,"(b) Preference allocation for employment-based immigrants"],[0,"Aliens subject to the worldwide level specified in section 1151(d) of this title for employment-based immigrants in a fiscal year shall be allotted visas as follows:"],[0,"(1) Priority workers"],[1,"Visas shall first be made available in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraphs (4) and (5), to qualified immigrants who are aliens described in any of the following subparagraphs (A) through (C):"],[0,"(A) Aliens with extraordinary ability"],[2,"An alien is described in this subparagraph if—"],[3,"(i) the alien has extraordinary ability in the sciences, arts, education, business, or athletics which has been demonstrated by sustained national or international acclaim and whose achievements have been recognized in the field through extensive documentation,"],[3,"(ii) the alien seeks to enter the United States to continue work in the area of extraordinary ability, and"],[3,"(iii) the alien's entry into the United States will substantially benefit prospectively the United States."],[0,"(B) Outstanding professors and researchers"],[2,"An alien is described in this subparagraph if—"],[3,"(i) the alien is recognized internationally as outstanding in a specific academic area,"],[3,"(ii) the alien has at least 3 years of experience in teaching or research in the academic area, and"],[3,"(iii) the alien seeks to enter the United States—"],[4,"(I) for a tenured position (or tenure-track position) within a university or institution of higher education to teach in the academic area,"],[4,"(II) for a comparable position with a university or institution of higher education to conduct research in the area, or"],[4,"(III) for a comparable position to conduct research in the area with a department, division, or institute of a private employer, if the department, division, or institute employs at least 3 persons full-time in research activities and has achieved documented accomplishments in an academic field."],[0,"(C) Certain multinational executives and managers"],[2,"An alien is described in this subparagraph if the alien, in the 3 years preceding the time of the alien's application for classification and admission into the United States under this subparagraph, has been employed for at least 1 year by a firm or corporation or other legal entity or an affiliate or subsidiary thereof and the alien seeks to enter the United States in order to continue to render services to the same employer or to a subsidiary or affiliate thereof in a capacity that is managerial or executive."],[0,"(2) Aliens who are members of the professions holding advanced degrees or aliens of exceptional ability"],[0,"(A) In general"],[2,"Visas shall be made available, in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraph (1), to qualified immigrants who are members of the professions holding advanced degrees or their equivalent or who because of their exceptional ability in the sciences, arts, or business, will substantially benefit prospectively the national economy, cultural or educational interests, or welfare of the United States, and whose services in the sciences, arts, professions, or business are sought by an employer in the United States."],[0,"(B) Waiver of job offer"],[0,"(i) National interest waiver"],[3,"Subject to clause (ii), the Attorney General may, when the Attorney General deems it to be in the national interest, waive the requirements of subparagraph (A) that an alien's services in the sciences, arts, professions, or business be sought by an employer in the United States."],[0,"(ii) Physicians working in shortage areas or veterans facilities"],[0,"(I) In general"],[4,"The Attorney General shall grant a national interest waiver pursuant to clause (i) on behalf of any alien physician with respect to whom a petition for preference classification has been filed under subparagraph (A) if—"],[5,"(aa) the alien physician agrees to work full time as a physician in an area or areas designated by the Secretary of Health and Human Services as having a shortage of health care professionals or at a health care facility under the jurisdiction of the Secretary of Veterans Affairs; and"],[5,"(bb) a Federal agency or a department of public health in any State has previously determined that the alien physician's work in such an area or at such facility was in the public interest."],[0,"(II) Prohibition"],[4,"No permanent resident visa may be issued to an alien physician described in subclause (I) by the Secretary of State under section 1154(b) of this title, and the Attorney General may not adjust the status of such an alien physician from that of a nonimmigrant alien to that of a permanent resident alien under section 1255 of this title, until such time as the alien has worked full time as a physician for an aggregate of 5 years (not including the time served in the status of an alien described in section 1101(a)(15)(J) of this title), in an area or areas designated by the Secretary of Health and Human Services as having a shortage of health care professionals or at a health care facility under the jurisdiction of the Secretary of Veterans Affairs."],[0,"(III) Statutory construction"],[4,"Nothing in this subparagraph may be construed to prevent the filing of a petition with the Attorney General for classification under section 1154(a) of this title, or the filing of an application for adjustment of status under section 1255 of this title, by an alien physician described in subclause (I) prior to the date by which such alien physician has completed the service described in subclause (II)."],[0,"(IV) Effective date"],[4,"The requirements of this subsection do not affect waivers on behalf of alien physicians approved under subsection (b)(2)(B) before the enactment date of this subsection. In the case of a physician for whom an application for a waiver was filed under subsection (b)(2)(B) prior to November 1, 1998, the Attorney General shall grant a national interest waiver pursuant to subsection (b)(2)(B) except that the alien is required to have worked full time as a physician for an aggregate of 3 years (not including time served in the status of an alien described in section 1101(a)(15)(J) of this title) before a visa can be issued to the alien under section 1154(b) of this title or the status of the alien is adjusted to permanent resident under section 1255 of this title."],[0,"(C) Determination of exceptional ability"],[2,"In determining under subparagraph (A) whether an immigrant has exceptional ability, the possession of a degree, diploma, certificate, or similar award from a college, university, school, or other institution of learning or a license to practice or certification for a particular profession or occupation shall not by itself be considered sufficient evidence of such exceptional ability."],[0,"(3) Skilled workers, professionals, and other workers"],[0,"(A) In general"],[2,"Visas shall be made available, in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraphs (1) and (2), to the following classes of aliens who are not described in paragraph (2):"],[0,"(i) Skilled workers"],[3,"Qualified immigrants who are capable, at the time of petitioning for classification under this paragraph, of performing skilled labor (requiring at least 2 years training or experience), not of a temporary or seasonal nature, for which qualified workers are not available in the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1153?type=usc&year=mostrecent&link-type=html"},"head":"§1153. Allocation of immigrant visas","tname":"Aliens and Nationality","by":{"0":"31, 9","1":"2","2":"8"}},{"t":"usc","label":"8 U.S.C. § 1154","url":"https://www.law.cornell.edu/uscode/text/8/1154","subs":["(a)","(a)(1)(A)(viii)(I)","(a)(1)(B)(ii)","(a)(1)(J)","(b)","(c)","(h)","(c)(1)"],"stext":{"head":"§1154. Procedure for granting immigrant status","paras":[[0,"(a) Petitioning procedure"],[0,"(1)(A)(i) Except as provided in clause (viii), any citizen of the United States claiming that an alien is entitled to classification by reason of a relationship described in paragraph (1), (3), or (4) of section 1153(a) of this title or to an immediate relative status under section 1151(b)(2)(A)(i) of this title may file a petition with the Attorney General for such classification."],[0,"(ii) An alien spouse described in the second sentence of section 1151(b)(2)(A)(i) of this title also may file a petition with the Attorney General under this subparagraph for classification of the alien (and the alien's children) under such section."],[0,"(iii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the United States citizen was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this subclause is an alien—"],[1,"(aa)(AA) who is the spouse of a citizen of the United States;"],[1,"(BB) who believed that he or she had married a citizen of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such citizen of the United States; or"],[1,"(CC) who was a bona fide spouse of a United States citizen within the past 2 years and—"],[2,"(aaa) whose spouse died within the past 2 years;"],[2,"(bbb) whose spouse lost or renounced citizenship status within the past 2 years related to an incident of domestic violence; or"],[2,"(ccc) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the United States citizen spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title or who would have been so classified but for the bigamy of the citizen of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iv) An alien who is the child of a citizen of the United States, or who was a child of a United States citizen parent who within the past 2 years lost or renounced citizenship status related to an incident of domestic violence, and who is a person of good moral character, who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title, and who resides, or has resided in the past, with the citizen parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's citizen parent. For purposes of this clause, residence includes any period of visitation."],[0,"(v) An alien who—"],[1,"(I) is the spouse, intended spouse, or child living abroad of a citizen who—"],[2,"(aa) is an employee of the United States Government;"],[2,"(bb) is a member of the uniformed services (as defined in section 101(a) of title 10); or"],[2,"(cc) has subjected the alien or the alien's child to battery or extreme cruelty in the United States; and"],[1,"(II) is eligible to file a petition under clause (iii) or (iv),"],[0,"shall file such petition with the Attorney General under the procedures that apply to self-petitioners under clause (iii) or (iv), as applicable."],[0,"(vi) For the purposes of any petition filed under clause (iii) or (iv), the denaturalization, loss or renunciation of citizenship, death of the abuser, divorce, or changes to the abuser's citizenship status after filing of the petition shall not adversely affect the approval of the petition, and for approved petitions shall not preclude the classification of the eligible self-petitioning spouse or child as an immediate relative or affect the alien's ability to adjust status under subsections (a) and (c) of section 1255 of this title or obtain status as a lawful permanent resident based on the approved self-petition under such clauses."],[0,"(vii) An alien may file a petition with the Secretary of Homeland Security under this subparagraph for classification of the alien under section 1151(b)(2)(A)(i) of this title if the alien—"],[1,"(I) is the parent of a citizen of the United States or was a parent of a citizen of the United States who, within the past 2 years, lost or renounced citizenship status related to an incident of domestic violence or died;"],[1,"(II) is a person of good moral character;"],[1,"(III) is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title;"],[1,"(IV) resides, or has resided, with the citizen daughter or son; and"],[1,"(V) demonstrates that the alien has been battered or subject to extreme cruelty by the citizen daughter or son."],[0,"(viii)(I) Clause (i) shall not apply to a citizen of the United States who has been convicted of a specified offense against a minor, unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that the citizen poses no risk to the alien with respect to whom a petition described in clause (i) is filed."],[0,"(II) For purposes of subclause (I), the term \"specified offense against a minor\" is defined as in section 20911 of title 34."],[0,"(B)(i)(I) Except as provided in subclause (II), any alien lawfully admitted for permanent residence claiming that an alien is entitled to a classification by reason of the relationship described in section 1153(a)(2) of this title may file a petition with the Attorney General for such classification."],[0,"(I) 1 Subclause (I) shall not apply in the case of an alien lawfully admitted for permanent residence who has been convicted of a specified offense against a minor (as defined in subparagraph (A)(viii)(II)), unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that such person poses no risk to the alien with respect to whom a petition described in subclause (I) is filed."],[0,"(ii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if such a child has not been classified under clause (iii) of section 1153(a)(2)(A) of this title and if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the lawful permanent resident was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this paragraph is an alien—"],[1,"(aa)(AA) who is the spouse of a lawful permanent resident of the United States; or"],[1,"(BB) who believed that he or she had married a lawful permanent resident of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such lawful permanent resident of the United States; or"],[1,"(CC) who was a bona fide spouse of a lawful permanent resident within the past 2 years and—"],[2,"(aaa) whose spouse lost status within the past 2 years due to an incident of domestic violence; or"],[2,"(bbb) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the lawful permanent resident spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as a spouse of an alien lawfully admitted for permanent residence under section 1153(a)(2)(A) of this title or who would have been so classified but for the bigamy of the lawful permanent resident of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iii) An alien who is the child of an alien lawfully admitted for permanent residence, or who was the child of a lawful permanent resident who within the past 2 years lost lawful permanent resident status due to an incident of domestic violence, and who is a person of good moral character, who is eligible for classification under section 1153(a)(2)(A) of this title, and who resides, or has resided in the past, with the alien's permanent resident alien parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's permanent resident parent."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1154?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1154. Procedure for granting immigrant status","tname":"Aliens and Nationality","by":{"0":"6, 6, 44, 6, 6, 47, 2, 6, 9, 43, 2, 7, 15, 26, 18, 21, 30, 45","1":"2, 2, 2, 2, 7, 11, 21, 22, 25, 26, 3, 7, 19, 21","2":"2, 6, 7, 5"}},{"t":"usc","label":"8 U.S.C. § 1155","url":"https://www.law.cornell.edu/uscode/text/8/1155","stext":{"head":"§1155. Revocation of approval of petitions; effective date","paras":[[0,"The Secretary of Homeland Security may, at any time, for what he deems to be good and sufficient cause, revoke the approval of any petition approved by him under section 1154 of this title. Such revocation shall be effective as of the date of approval of any such petition."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1155?type=usc&year=mostrecent&link-type=html"},"op":22,"ar":3,"head":"§1155. Revocation of approval of petitions; effective date","tname":"Aliens and Nationality","by":{"0":"8, 16, 30","1":"14","2":"2, 5, 7"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(1)"],"stext":{"head":"§1158. Asylum","paras":[[0,"(a) Authority to apply for asylum"],[0,"(1) In general"],[1,"Any alien who is physically present in the United States or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters), irrespective of such alien's status, may apply for asylum in accordance with this section or, where applicable, section 1225(b) of this title."],[0,"(2) Exceptions"],[0,"(A) Safe third country"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that the alien may be removed, pursuant to a bilateral or multilateral agreement, to a country (other than the country of the alien's nationality or, in the case of an alien having no nationality, the country of the alien's last habitual residence) in which the alien's life or freedom would not be threatened on account of race, religion, nationality, membership in a particular social group, or political opinion, and where the alien would have access to a full and fair procedure for determining a claim to asylum or equivalent temporary protection, unless the Attorney General finds that it is in the public interest for the alien to receive asylum in the United States."],[0,"(B) Time limit"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien unless the alien demonstrates by clear and convincing evidence that the application has been filed within 1 year after the date of the alien's arrival in the United States."],[0,"(C) Previous asylum applications"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien if the alien has previously applied for asylum and had such application denied."],[0,"(D) Changed circumstances"],[2,"An application for asylum of an alien may be considered, notwithstanding subparagraphs (B) and (C), if the alien demonstrates to the satisfaction of the Attorney General either the existence of changed circumstances which materially affect the applicant's eligibility for asylum or extraordinary circumstances relating to the delay in filing an application within the period specified in subparagraph (B)."],[0,"(E) Applicability"],[2,"Subparagraphs (A) and (B) shall not apply to an unaccompanied alien child (as defined in section 279(g) of title 6)."],[0,"(3) Limitation on judicial review"],[1,"No court shall have jurisdiction to review any determination of the Attorney General under paragraph (2)."],[0,"(b) Conditions for granting asylum"],[0,"(1) In general"],[0,"(A) Eligibility"],[2,"The Secretary of Homeland Security or the Attorney General may grant asylum to an alien who has applied for asylum in accordance with the requirements and procedures established by the Secretary of Homeland Security or the Attorney General under this section if the Secretary of Homeland Security or the Attorney General determines that such alien is a refugee within the meaning of section 1101(a)(42)(A) of this title."],[0,"(B) Burden of proof"],[0,"(i) In general"],[3,"The burden of proof is on the applicant to establish that the applicant is a refugee, within the meaning of section 1101(a)(42)(A) of this title. To establish that the applicant is a refugee within the meaning of such section, the applicant must establish that race, religion, nationality, membership in a particular social group, or political opinion was or will be at least one central reason for persecuting the applicant."],[0,"(ii) Sustaining burden"],[3,"The testimony of the applicant may be sufficient to sustain the applicant's burden without corroboration, but only if the applicant satisfies the trier of fact that the applicant's testimony is credible, is persuasive, and refers to specific facts sufficient to demonstrate that the applicant is a refugee. In determining whether the applicant has met the applicant's burden, the trier of fact may weigh the credible testimony along with other evidence of record. Where the trier of fact determines that the applicant should provide evidence that corroborates otherwise credible testimony, such evidence must be provided unless the applicant does not have the evidence and cannot reasonably obtain the evidence."],[0,"(iii) Credibility determination"],[3,"Considering the totality of the circumstances, and all relevant factors, a trier of fact may base a credibility determination on the demeanor, candor, or responsiveness of the applicant or witness, the inherent plausibility of the applicant's or witness's account, the consistency between the applicant's or witness's written and oral statements (whenever made and whether or not under oath, and considering the circumstances under which the statements were made), the internal consistency of each such statement, the consistency of such statements with other evidence of record (including the reports of the Department of State on country conditions), and any inaccuracies or falsehoods in such statements, without regard to whether an inconsistency, inaccuracy, or falsehood goes to the heart of the applicant's claim, or any other relevant factor. There is no presumption of credibility, however, if no adverse credibility determination is explicitly made, the applicant or witness shall have a rebuttable presumption of credibility on appeal."],[0,"(2) Exceptions"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that—"],[3,"(i) the alien ordered, incited, assisted, or otherwise participated in the persecution of any person on account of race, religion, nationality, membership in a particular social group, or political opinion;"],[3,"(ii) the alien, having been convicted by a final judgment of a particularly serious crime, constitutes a danger to the community of the United States;"],[3,"(iii) there are serious reasons for believing that the alien has committed a serious nonpolitical crime outside the United States prior to the arrival of the alien in the United States;"],[3,"(iv) there are reasonable grounds for regarding the alien as a danger to the security of the United States;"],[3,"(v) the alien is described in subclause (I), (II), (III), (IV), or (VI) of section 1182(a)(3)(B)(i) of this title or section 1227(a)(4)(B) of this title (relating to terrorist activity), unless, in the case only of an alien described in subclause (IV) of section 1182(a)(3)(B)(i) of this title, the Attorney General determines, in the Attorney General's discretion, that there are not reasonable grounds for regarding the alien as a danger to the security of the United States; or"],[3,"(vi) the alien was firmly resettled in another country prior to arriving in the United States."],[0,"(B) Special rules"],[0,"(i) Conviction of aggravated felony"],[3,"For purposes of clause (ii) of subparagraph (A), an alien who has been convicted of an aggravated felony shall be considered to have been convicted of a particularly serious crime."],[0,"(ii) Offenses"],[3,"The Attorney General may designate by regulation offenses that will be considered to be a crime described in clause (ii) or (iii) of subparagraph (A)."],[0,"(C) Additional limitations"],[2,"The Attorney General may by regulation establish additional limitations and conditions, consistent with this section, under which an alien shall be ineligible for asylum under paragraph (1)."],[0,"(D) No judicial review"],[2,"There shall be no judicial review of a determination of the Attorney General under subparagraph (A)(v)."],[0,"(3) Treatment of spouse and children"],[0,"(A) In general"],[2,"A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of an alien who is granted asylum under this subsection may, if not otherwise eligible for asylum under this section, be granted the same status as the alien if accompanying, or following to join, such alien."],[0,"(B) Continued classification of certain aliens as children"],[2,"An unmarried alien who seeks to accompany, or follow to join, a parent granted asylum under this subsection, and who was under 21 years of age on the date on which such parent applied for asylum under this section, shall continue to be classified as a child for purposes of this paragraph and section 1159(b)(3) of this title, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(C) Initial jurisdiction"],[2,"An asylum officer (as defined in section 1225(b)(1)(E) of this title) shall have initial jurisdiction over any asylum application filed by an unaccompanied alien child (as defined in section 279(g) of title 6), regardless of whether filed in accordance with this section or section 1225(b) of this title."],[0,"(c) Asylum status"],[0,"(1) In general"],[1,"In the case of an alien granted asylum under subsection (b), the Attorney General—"],[2,"(A) shall not remove or return the alien to the alien's country of nationality or, in the case of a person having no nationality, the country of the alien's last habitual residence;"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with appropriate endorsement of that authorization; and"],[2,"(C) may allow the alien to travel abroad with the prior consent of the Attorney General."],[0,"(2) Termination of asylum"],[1,"Asylum granted under subsection (b) does not convey a right to remain permanently in the United States, and may be terminated if the Attorney General determines that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1158?type=usc&year=mostrecent&link-type=html"},"head":"§1158. Asylum","tname":"Aliens and Nationality","by":{"0":"34","1":"14"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(h)","(i)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"11, 11"}},{"t":"usc","label":"8 U.S.C. § 1186a","url":"https://www.law.cornell.edu/uscode/text/8/1186a","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1187","url":"https://www.law.cornell.edu/uscode/text/8/1187","subs":["(a)","(h)(3)(C)(iv)"],"stext":{"head":"§1187. Visa waiver program for certain visitors","paras":[[0,"(a) Establishment of program"],[0,"The Secretary of Homeland Security and the Secretary of State are authorized to establish a program (hereinafter in this section referred to as the \"program\") under which the requirement of paragraph (7)(B)(i)(II) of section 1182(a) of this title may be waived by the Secretary of Homeland Security, in consultation with the Secretary of State and in accordance with this section, in the case of an alien who meets the following requirements:"],[0,"(1) Seeking entry as tourist for 90 days or less"],[1,"The alien is applying for admission during the program as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) for a period not exceeding 90 days."],[0,"(2) National of program country"],[1,"The alien is a national of, and presents a passport issued by, a country which—"],[2,"(A) extends (or agrees to extend), either on its own or in conjunction with one or more other countries that are described in subparagraph (B) and that have established with it a common area for immigration admissions, reciprocal privileges to citizens and nationals of the United States, and"],[2,"(B) is designated as a pilot program country under subsection (c)."],[0,"(3) Passport requirements"],[1,"The alien, at the time of application for admission, is in possession of a valid unexpired passport that satisfies the following:"],[0,"(A) Machine readable"],[2,"The passport is a machine-readable passport that is tamper-resistant, incorporates document authentication identifiers, and otherwise satisfies the internationally accepted standard for machine readability."],[0,"(B) Electronic"],[2,"Beginning on April 1, 2016, the passport is an electronic passport that is fraud-resistant, contains relevant biographic and biometric information (as determined by the Secretary of Homeland Security), and otherwise satisfies internationally accepted standards for electronic passports."],[0,"(4) Executes immigration forms"],[1,"The alien before the time of such admission completes such immigration form as the Secretary of Homeland Security shall establish."],[0,"(5) Entry into the United States"],[1,"If arriving by sea or air, the alien arrives at the port of entry into the United States on a carrier, including any carrier conducting operations under part 135 of title 14, Code of Federal Regulations, or a noncommercial aircraft that is owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations 1 which has entered into an agreement with the Secretary of Homeland Security pursuant to subsection (e). The Secretary of Homeland Security is authorized to require a carrier conducting operations under part 135 of title 14, Code of Federal Regulations, or a domestic corporation conducting operations under part 91 of that title, to give suitable and proper bond, in such reasonable amount and containing such conditions as the Secretary of Homeland Security may deem sufficient to ensure compliance with the indemnification requirements of this section, as a term of such an agreement."],[0,"(6) Not a safety threat"],[1,"The alien has been determined not to represent a threat to the welfare, health, safety, or security of the United States."],[0,"(7) No previous violation"],[1,"If the alien previously was admitted without a visa under this section, the alien must not have failed to comply with the conditions of any previous admission as such a nonimmigrant."],[0,"(8) Round-trip ticket"],[1,"The alien is in possession of a round-trip transportation ticket (unless this requirement is waived by the Secretary of Homeland Security under regulations or the alien is arriving at the port of entry on an aircraft operated under part 135 of title 14, Code of Federal Regulations, or a noncommercial aircraft that is owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations)."],[0,"(9) Automated system check"],[1,"The identity of the alien has been checked using an automated electronic database containing information about the inadmissibility of aliens to uncover any grounds on which the alien may be inadmissible to the United States, and no such ground has been found."],[0,"(10) Electronic transmission of identification information"],[1,"Operators of aircraft under part 135 of title 14, Code of Federal Regulations, or operators of noncommercial aircraft that are owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations, carrying any alien passenger who will apply for admission under this section shall furnish such information as the Secretary of Homeland Security by regulation shall prescribe as necessary for the identification of any alien passenger being transported and for the enforcement of the immigration laws. Such information shall be electronically transmitted not less than one hour prior to arrival at the port of entry for purposes of checking for inadmissibility using the automated electronic database."],[0,"(11) Eligibility determination under the electronic system for travel authorization"],[1,"Beginning on the date on which the electronic system for travel authorization developed under subsection (h)(3) is fully operational, each alien traveling under the program shall, before applying for admission to the United States, electronically provide to the system biographical information and such other information as the Secretary of Homeland Security shall determine necessary to determine the eligibility of, and whether there exists a law enforcement or security risk in permitting, the alien to travel to the United States. Upon review of such biographical information, the Secretary of Homeland Security shall determine whether the alien is eligible to travel to the United States under the program."],[0,"(12) Not present in Iraq, Syria, or any other country or area of concern"],[0,"(A) In general"],[2,"Except as provided in subparagraphs (B) and (C)—"],[3,"(i) the alien has not been present, at any time on or after March 1, 2011—"],[4,"(I) in Iraq or Syria;"],[4,"(II) in a country that is designated by the Secretary of State under section 4605(j) 2 of title 50 (as continued in effect under the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.)), section 2780 of title 22, section 2371 of title 22, or any other provision of law, as a country, the government of which has repeatedly provided support of acts of international terrorism; or"],[4,"(III) in any other country or area of concern designated by the Secretary of Homeland Security under subparagraph (D); and"],[3,"(ii) regardless of whether the alien is a national of a program country, the alien is not a national of—"],[4,"(I) Iraq or Syria;"],[4,"(II) a country that is designated, at the time the alien applies for admission, by the Secretary of State under section 4605(j) 2 of title 50 (as continued in effect under the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.)), section 2780 of title 22, section 2371 of title 22, or any other provision of law, as a country, the government of which has repeatedly provided support of acts of international terrorism; or"],[4,"(III) any other country that is designated, at the time the alien applies for admission, by the Secretary of Homeland Security under subparagraph (D)."],[0,"(B) Certain military personnel and government employees"],[2,"Subparagraph (A)(i) shall not apply in the case of an alien if the Secretary of Homeland Security determines that the alien was present—"],[3,"(i) in order to perform military service in the armed forces of a program country; or"],[3,"(ii) in order to carry out official duties as a full time employee of the government of a program country."],[0,"(C) Waiver"],[2,"The Secretary of Homeland Security may waive the application of subparagraph (A) to an alien if the Secretary determines that such a waiver is in the law enforcement or national security interests of the United States."],[0,"(D) Countries or areas of concern"],[0,"(i) In general"],[3,"Not later than 60 days after December 18, 2015, the Secretary of Homeland Security, in consultation with the Secretary of State and the Director of National Intelligence, shall determine whether the requirement under subparagraph (A) shall apply to any other country or area."],[0,"(ii) Criteria"],[3,"In making a determination under clause (i), the Secretary shall consider—"],[4,"(I) whether the presence of an alien in the country or area increases the likelihood that the alien is a credible threat to the national security of the United States;"],[4,"(II) whether a foreign terrorist organization has a significant presence in the country or area; and"],[4,"(III) whether the country or area is a safe haven for terrorists."],[0,"(iii) Annual review"],[3,"The Secretary shall conduct a review, on an annual basis, of any determination made under clause (i)."],[0,"(E) Report"],[2,"Beginning not later than one year after December 18, 2015, and annually thereafter, the Secretary of Homeland Security shall submit to the Committee on Homeland Security, the Committee on Foreign Affairs, the Permanent Select Committee on Intelligence, and the Committee on the Judiciary of the House of Representatives, and the Committee on Homeland Security and Governmental Affairs, the Committee on Foreign Relations, the Select Committee on Intelligence, and the Committee on the Judiciary of the Senate a report on each instance in which the Secretary exercised the waiver authority under subparagraph (C) during the previous year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1187?type=usc&year=mostrecent&link-type=html"},"head":"§1187. Visa waiver program for certain visitors","tname":"Aliens and Nationality","by":{"0":"34","2":"19"}},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","subs":["(i)","(a)"],"stext":{"head":"§1201. Issuance of visas","paras":[[0,"(a) Immigrants; nonimmigrants"],[0,"(1) Under the conditions hereinafter prescribed and subject to the limitations prescribed in this chapter or regulations issued thereunder, a consular officer may issue"],[1,"(A) to an immigrant who has made proper application therefor, an immigrant visa which shall consist of the application provided for in section 1202 of this title, visaed by such consular officer, and shall specify the foreign state, if any, to which the immigrant is charged, the immigrant's particular status under such foreign state, the preference, immediate relative, or special immigrant classification to which the alien is charged, the date on which the validity of the visa shall expire, and such additional information as may be required; and"],[1,"(B) to a nonimmigrant who has made proper application therefor, a nonimmigrant visa, which shall specify the classification under section 1101(a)(15) of this title of the nonimmigrant, the period during which the nonimmigrant visa shall be valid, and such additional information as may be required."],[0,"(2) The Secretary of State shall provide to the Service an electronic version of the visa file of each alien who has been issued a visa to ensure that the data in that visa file is available to immigration inspectors at the United States ports of entry before the arrival of the alien at such a port of entry."],[0,"(b) Registration; photographs; waiver of requirement"],[0,"Each alien who applies for a visa shall be registered in connection with his application, and shall furnish copies of his photograph signed by him for such use as may be by regulations required. The requirements of this subsection may be waived in the discretion of the Secretary of State in the case of any alien who is within that class of nonimmigrants enumerated in sections 1101(a)(15)(A), and 1101(a)(15)(G) of this title, or in the case of any alien who is granted a diplomatic visa on a diplomatic passport or on the equivalent thereof."],[0,"(c) Period of validity; renewal or replacement"],[0,"(1) Immigrant visas"],[1,"An immigrant visa shall be valid for such period, not exceeding six months, as shall be by regulations prescribed, except that any visa issued to a child lawfully adopted by a United States citizen and spouse while such citizen is serving abroad in the United States Armed Forces, or is employed abroad by the United States Government, or is temporarily abroad on business, shall be valid until such time, for a period not to exceed three years, as the adoptive citizen parent returns to the United States in due course of his service, employment, or business."],[0,"(2) Nonimmigrant visas"],[1,"A nonimmigrant visa shall be valid for such periods as shall be by regulations prescribed. In prescribing the period of validity of a nonimmigrant visa in the case of nationals of any foreign country who are eligible for such visas, the Secretary of State shall, insofar as practicable, accord to such nationals the same treatment upon a reciprocal basis as such foreign country accords to nationals of the United States who are within a similar class; except that in the case of aliens who are nationals of a foreign country and who either are granted refugee status and firmly resettled in another foreign country or are granted permanent residence and residing in another foreign country, the Secretary of State may prescribe the period of validity of such a visa based upon the treatment granted by that other foreign country to alien refugees and permanent residents, respectively, in the United States."],[0,"(3) Visa replacement"],[1,"An immigrant visa may be replaced under the original number during the fiscal year in which the original visa was issued for an immigrant who establishes to the satisfaction of the consular officer that the immigrant—"],[2,"(A) was unable to use the original immigrant visa during the period of its validity because of reasons beyond his control and for which he was not responsible;"],[2,"(B) is found by a consular officer to be eligible for an immigrant visa; and"],[2,"(C) pays again the statutory fees for an application and an immigrant visa."],[0,"(4) Fee waiver"],[1,"If an immigrant visa was issued, on or after March 27, 2013, for a child who has been lawfully adopted, or who is coming to the United States to be adopted, by a United States citizen, any statutory immigrant visa fees relating to a renewal or replacement of such visa may be waived or, if already paid, may be refunded upon request, subject to such criteria as the Secretary of State may prescribe, if—"],[2,"(A) the immigrant child was unable to use the original immigrant visa during the period of its validity as a direct result of extraordinary circumstances, including the denial of an exit permit; and"],[2,"(B) if such inability was attributable to factors beyond the control of the adopting parent or parents and of the immigrant."],[0,"(d) Physical examination"],[0,"Prior to the issuance of an immigrant visa to any alien, the consular officer shall require such alien to submit to a physical and mental examination in accordance with such regulations as may be prescribed. Prior to the issuance of a nonimmigrant visa to any alien, the consular officer may require such alien to submit to a physical or mental examination, or both, if in his opinion such examination is necessary to ascertain whether such alien is eligible to receive a visa."],[0,"(e) Surrender of visa"],[0,"Each immigrant shall surrender his immigrant visa to the immigration officer at the port of entry, who shall endorse on the visa the date and the port of arrival, the identity of the vessel or other means of transportation by which the immigrant arrived, and such other endorsements as may be by regulations required."],[0,"(f) Surrender of documents"],[0,"Each nonimmigrant shall present or surrender to the immigration officer at the port of entry such documents as may be by regulation required. In the case of an alien crewman not in possession of any individual documents other than a passport and until such time as it becomes practicable to issue individual documents, such alien crewman may be admitted, subject to the provisions of this part, if his name appears in the crew list of the vessel or aircraft on which he arrives and the crew list is visaed by a consular officer, but the consular officer shall have the right to deny admission to any alien crewman from the crew list visa."],[0,"(g) Nonissuance of visas or other documents"],[0,"No visa or other documentation shall be issued to an alien if (1) it appears to the consular officer, from statements in the application, or in the papers submitted therewith, that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law, (2) the application fails to comply with the provisions of this chapter, or the regulations issued thereunder, or (3) the consular officer knows or has reason to believe that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law: Provided, That a visa or other documentation may be issued to an alien who is within the purview of section 1182(a)(4) of this title, if such alien is otherwise entitled to receive a visa or other documentation, upon receipt of notice by the consular officer from the Attorney General of the giving of a bond or undertaking providing indemnity as in the case of aliens admitted under section 1183 of this title: Provided further, That a visa may be issued to an alien defined in section 1101(a)(15)(B) or (F) of this title, if such alien is otherwise entitled to receive a visa, upon receipt of a notice by the consular officer from the Attorney General of the giving of a bond with sufficient surety in such sum and containing such conditions as the consular officer shall prescribe, to insure that at the expiration of the time for which such alien has been admitted by the Attorney General, as provided in section 1184(a) of this title, or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States."],[0,"(h) Nonadmission upon arrival"],[0,"Nothing in this chapter shall be construed to entitle any alien, to whom a visa or other documentation has been issued, to be admitted 1 the United States, if, upon arrival at a port of entry in the United States, he is found to be inadmissible under this chapter, or any other provision of law. The substance of this subsection shall appear upon every visa application."],[0,"(i) Revocation of visas or documents"],[0,"After the issuance of a visa or other documentation to any alien, the consular officer or the Secretary of State may at any time, in his discretion, revoke such visa or other documentation. Notice of such revocation shall be communicated to the Attorney General, and such revocation shall invalidate the visa or other documentation from the date of issuance: Provided, That carriers or transportation companies, and masters, commanding officers, agents, owners, charterers, or consignees, shall not be penalized under section 1323(b) of this title for action taken in reliance on such visas or other documentation, unless they received due notice of such revocation prior to the alien's embarkation. There shall be no means of judicial review (including review pursuant to section 2241 of title 28 or any other habeas corpus provision, and sections 1361 and 1651 of such title) of a revocation under this subsection, except in the context of a removal proceeding if such revocation provides the sole ground for removal under section 1227(a)(1)(B) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1201?type=usc&year=mostrecent&link-type=html"},"head":"§1201. Issuance of visas","tname":"Aliens and Nationality","by":{"0":"4, 20, 42","1":"3","2":"18"}},{"t":"usc","label":"8 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/8/1204","stext":{"head":"§1204. Immediate relative and special immigrant visas","paras":[[0,"A consular officer may, subject to the limitations provided in section 1201 of this title, issue an immigrant visa to a special immigrant or immediate relative as such upon satisfactory proof, under regulations prescribed under this chapter, that the applicant is entitled to special immigrant or immediate relative status."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1204?type=usc&year=mostrecent&link-type=html"},"head":"§1204. Immediate relative and special immigrant visas","tname":"Aliens and Nationality","by":{"0":"7, 28","2":"6"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)","(b)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"head":"§1229b. Cancellation of removal; adjustment of status","tname":"Aliens and Nationality","by":{"0":"11","1":"15, 19, 15"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","subs":["(a)(1)"],"stext":{"head":"§1229c. Voluntary departure","paras":[[0,"(a) Certain conditions"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense under this subsection, in lieu of being subject to proceedings under section 1229a of this title or prior to the completion of such proceedings, if the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4)(B) of this title."],[0,"(2) Period"],[0,"(A) In general"],[2,"Subject to subparagraph (B), permission to depart voluntarily under this subsection shall not be valid for a period exceeding 120 days."],[0,"(B) Three-year pilot program waiver"],[2,"During the period October 1, 2000, through September 30, 2003, and subject to subparagraphs (C) and (D)(ii), the Attorney General may, in the discretion of the Attorney General for humanitarian purposes, waive application of subparagraph (A) in the case of an alien—"],[3,"(i) who was admitted to the United States as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) under the provisions of the visa waiver pilot program established pursuant to section 1187 of this title, seeks the waiver for the purpose of continuing to receive medical treatment in the United States from a physician associated with a health care facility, and submits to the Attorney General—"],[4,"(I) a detailed diagnosis statement from the physician, which includes the treatment being sought and the expected time period the alien will be required to remain in the United States;"],[4,"(II) a statement from the health care facility containing an assurance that the alien's treatment is not being paid through any Federal or State public health assistance, that the alien's account has no outstanding balance, and that such facility will notify the Service when the alien is released or treatment is terminated; and"],[4,"(III) evidence of financial ability to support the alien's day-to-day expenses while in the United States (including the expenses of any family member described in clause (ii)) and evidence that any such alien or family member is not receiving any form of public assistance; or"],[3,"(ii) who—"],[4,"(I) is a spouse, parent, brother, sister, son, daughter, or other family member of a principal alien described in clause (i); and"],[4,"(II) entered the United States accompanying, and with the same status as, such principal alien."],[0,"(C) Waiver limitations"],[2,"(i) Waivers under subparagraph (B) may be granted only upon a request submitted by a Service district office to Service headquarters."],[2,"(ii) Not more than 300 waivers may be granted for any fiscal year for a principal alien under subparagraph (B)(i)."],[2,"(iii)(I) Except as provided in subclause (II), in the case of each principal alien described in subparagraph (B)(i) not more than one adult may be granted a waiver under subparagraph (B)(ii)."],[2,"(II) Not more than two adults may be granted a waiver under subparagraph (B)(ii) in a case in which—"],[3,"(aa) the principal alien described in subparagraph (B)(i) is a dependent under the age of 18; or"],[3,"(bb) one such adult is age 55 or older or is physically handicapped."],[0,"(D) Report to Congress; suspension of waiver authority"],[2,"(i) Not later than March 30 of each year, the Commissioner shall submit to the Congress an annual report regarding all waivers granted under subparagraph (B) during the preceding fiscal year."],[2,"(ii) Notwithstanding any other provision of law, the authority of the Attorney General under subparagraph (B) shall be suspended during any period in which an annual report under clause (i) is past due and has not been submitted."],[0,"(3) Bond"],[1,"The Attorney General may require an alien permitted to depart voluntarily under this subsection to post a voluntary departure bond, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(4) Treatment of aliens arriving in the United States"],[1,"In the case of an alien who is arriving in the United States and with respect to whom proceedings under section 1229a of this title are (or would otherwise be) initiated at the time of such alien's arrival, paragraph (1) shall not apply. Nothing in this paragraph shall be construed as preventing such an alien from withdrawing the application for admission in accordance with section 1225(a)(4) of this title."],[0,"(b) At conclusion of proceedings"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense if, at the conclusion of a proceeding under section 1229a of this title, the immigration judge enters an order granting voluntary departure in lieu of removal and finds that—"],[2,"(A) the alien has been physically present in the United States for a period of at least one year immediately preceding the date the notice to appear was served under section 1229(a) of this title;"],[2,"(B) the alien is, and has been, a person of good moral character for at least 5 years immediately preceding the alien's application for voluntary departure;"],[2,"(C) the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4) of this title; and"],[2,"(D) the alien has established by clear and convincing evidence that the alien has the means to depart the United States and intends to do so."],[0,"(2) Period"],[1,"Permission to depart voluntarily under this subsection shall not be valid for a period exceeding 60 days."],[0,"(3) Bond"],[1,"An alien permitted to depart voluntarily under this subsection shall be required to post a voluntary departure bond, in an amount necessary to ensure that the alien will depart, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(c) Aliens not eligible"],[0,"The Attorney General shall not permit an alien to depart voluntarily under this section if the alien was previously permitted to so depart after having been found inadmissible under section 1182(a)(6)(A) of this title."],[0,"(d) Civil penalty for failure to depart"],[0,"(1) In general"],[1,"Subject to paragraph (2), if an alien is permitted to depart voluntarily under this section and voluntarily fails to depart the United States within the time period specified, the alien—"],[2,"(A) shall be subject to a civil penalty of not less than $1,000 and not more than $5,000; and"],[2,"(B) shall be ineligible, for a period of 10 years, to receive any further relief under this section and sections 1229b, 1255, 1258, and 1259 of this title."],[0,"(2) Application of VAWA protections"],[1,"The restrictions on relief under paragraph (1) shall not apply to relief under section 1229b or 1255 of this title on the basis of a petition filed by a VAWA self-petitioner, or a petition filed under section 1229b(b)(2) of this title, or under section 1254(a)(3) of this title (as in effect prior to March 31, 1997), if the extreme cruelty or battery was at least one central reason for the alien's overstaying the grant of voluntary departure."],[0,"(3) Notice of penalties"],[1,"The order permitting an alien to depart voluntarily shall inform the alien of the penalties under this subsection."],[0,"(e) Additional conditions"],[0,"The Attorney General may by regulation limit eligibility for voluntary departure under this section for any class or classes of aliens. No court may review any regulation issued under this subsection."],[0,"(f) Judicial review"],[0,"No court shall have jurisdiction over an appeal from denial of a request for an order of voluntary departure under subsection (b), nor shall any court order a stay of an alien's removal pending consideration of any claim with respect to voluntary departure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229c?type=usc&year=mostrecent&link-type=html"},"head":"§1229c. Voluntary departure","tname":"Aliens and Nationality","by":{"0":"11","1":"15"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(2)(A)(i)","(a)(2)(B)","(a)(2)(B)(i)","(a)(2)(B)(ii)","(a)(2)(D)","(a)(1)","(a)(2)(A)","(a)(2)(C)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"41, 11, 20, 22, 41, 48, 49, 3, 12, 16, 18, 24, 33","1":"3, 22, 3, 22, 3, 22, 3, 22, 3, 22, 3, 22, 3, 22","2":"17, 1, 4, 13, 16, 18, 12"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","subs":["(c)","(b)(5)(A)"],"by":{"0":"34","2":"18, 19"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(a)"],"stext":{"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","paras":[[0,"(a) Status as person admitted for permanent residence on application and eligibility for immigrant visa"],[0,"The status of an alien who was inspected and admitted or paroled into the United States or the status of any other alien having an approved petition for classification as a VAWA self-petitioner may be adjusted by the Attorney General, in his discretion and under such regulations as he may prescribe, to that of an alien lawfully admitted for permanent residence if (1) the alien makes an application for such adjustment, (2) the alien is eligible to receive an immigrant visa and is admissible to the United States for permanent residence, and (3) an immigrant visa is immediately available to him at the time his application is filed."],[0,"(b) Record of lawful admission for permanent residence; reduction of preference visas"],[0,"Upon the approval of an application for adjustment made under subsection (a), the Attorney General shall record the alien's lawful admission for permanent residence as of the date the order of the Attorney General approving the application for the adjustment of status is made, and the Secretary of State shall reduce by one the number of the preference visas authorized to be issued under sections 1152 and 1153 of this title within the class to which the alien is chargeable for the fiscal year then current."],[0,"(c) Alien crewmen, aliens continuing or accepting unauthorized employment, and aliens admitted in transit without visa"],[0,"Other than an alien having an approved petition for classification as a VAWA self-petitioner, subsection (a) shall not be applicable to (1) an alien crewman; (2) subject to subsection (k), an alien (other than an immediate relative as defined in section 1151(b) of this title or a special immigrant described in section 1101(a)(27)(H), (I), (J), or (K) of this title) who hereafter continues in or accepts unauthorized employment prior to filing an application for adjustment of status or who is in unlawful immigration status on the date of filing the application for adjustment of status or who has failed (other than through no fault of his own or for technical reasons) to maintain continuously a lawful status since entry into the United States; (3) any alien admitted in transit without visa under section 1182(d)(4)(C) of this title; (4) an alien (other than an immediate relative as defined in section 1151(b) of this title) who was admitted as a nonimmigrant visitor without a visa under section 1182(l) of this title or section 1187 of this title; (5) an alien who was admitted as a nonimmigrant described in section 1101(a)(15)(S) of this title,1 (6) an alien who is deportable under section 1227(a)(4)(B) of this title; (7) any alien who seeks adjustment of status to that of an immigrant under section 1153(b) of this title and is not in a lawful nonimmigrant status; or (8) any alien who was employed while the alien was an unauthorized alien, as defined in section 1324a(h)(3) of this title, or who has otherwise violated the terms of a nonimmigrant visa."],[0,"(d) Alien admitted for permanent residence on conditional basis; fiancee or fiance of citizen"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186a of this title. The Attorney General may not adjust, under subsection (a), the status of a nonimmigrant alien described in section 1101(a)(15)(K) of this title except to that of an alien lawfully admitted to the United States on a conditional basis under section 1186a of this title as a result of the marriage of the nonimmigrant (or, in the case of a minor child, the parent) to the citizen who filed the petition to accord that alien's nonimmigrant status under section 1101(a)(15)(K) of this title."],[0,"(e) Restriction on adjustment of status based on marriages entered while in admissibility or deportation proceedings; bona fide marriage exception"],[0,"(1) Except as provided in paragraph (3), an alien who is seeking to receive an immigrant visa on the basis of a marriage which was entered into during the period described in paragraph (2) may not have the alien's status adjusted under subsection (a)."],[0,"(2) The period described in this paragraph is the period during which administrative or judicial proceedings are pending regarding the alien's right to be admitted or remain in the United States."],[0,"(3) Paragraph (1) and section 1154(g) of this title shall not apply with respect to a marriage if the alien establishes by clear and convincing evidence to the satisfaction of the Attorney General that the marriage was entered into in good faith and in accordance with the laws of the place where the marriage took place and the marriage was not entered into for the purpose of procuring the alien's admission as an immigrant and no fee or other consideration was given (other than a fee or other consideration to an attorney for assistance in preparation of a lawful petition) for the filing of a petition under section 1154(a) of this title or subsection (d) or (p) 2 of section 1184 of this title with respect to the alien spouse or alien son or daughter. In accordance with regulations, there shall be only one level of administrative appellate review for each alien under the previous sentence."],[0,"(f) Limitation on adjustment of status"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186b of this title."],[0,"(g) Special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(K) of this title, such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States."],[0,"(h) Application with respect to special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(J) of this title—"],[1,"(1) such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States; and"],[1,"(2) in determining the alien's admissibility as an immigrant—"],[2,"(A) paragraphs (4), (5)(A), (6)(A), (6)(C), (6)(D), (7)(A), and (9)(B) of section 1182(a) of this title shall not apply; and"],[2,"(B) the Attorney General may waive other paragraphs of section 1182(a) of this title (other than paragraphs (2)(A), (2)(B), (2)(C) (except for so much of such paragraph as related to a single offense of simple possession of 30 grams or less of marijuana), (3)(A), (3)(B), (3)(C), and (3)(E)) in the case of individual aliens for humanitarian purposes, family unity, or when it is otherwise in the public interest."],[0,"The relationship between an alien and the alien's natural parents or prior adoptive parents shall not be considered a factor in making a waiver under paragraph (2)(B). Nothing in this subsection or section 1101(a)(27)(J) of this title shall be construed as authorizing an alien to apply for admission or be admitted to the United States in order to obtain special immigrant status described in such section."],[0,"(i) Adjustment in status of certain aliens physically present in United States"],[0,"(1) Notwithstanding the provisions of subsections (a) and (c) of this section, an alien physically present in the United States—"],[1,"(A) who—"],[2,"(i) entered the United States without inspection; or"],[2,"(ii) is within one of the classes enumerated in subsection (c) of this section;"],[1,"(B) who is the beneficiary (including a spouse or child of the principal alien, if eligible to receive a visa under section 1153(d) of this title) of—"],[2,"(i) a petition for classification under section 1154 of this title that was filed with the Attorney General on or before April 30, 2001; or"],[2,"(ii) an application for a labor certification under section 1182(a)(5)(A) of this title that was filed pursuant to the regulations of the Secretary of Labor on or before such date; and"],[1,"(C) who, in the case of a beneficiary of a petition for classification, or an application for labor certification, described in subparagraph (B) that was filed after January 14, 1998, is physically present in the United States on December 21, 2000;"],[0,"may apply to the Attorney General for the adjustment of his or her status to that of an alien lawfully admitted for permanent residence. The Attorney General may accept such application only if the alien remits with such application a sum equalling $1,000 as of the date of receipt of the application, but such sum shall not be required from a child under the age of seventeen, or an alien who is the spouse or unmarried child of an individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986 at any date, who—"],[1,"(i) as of May 5, 1988, was the unmarried child or spouse of the individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986;"],[1,"(ii) entered the United States before May 5, 1988, resided in the United States on May 5, 1988, and is not a lawful permanent resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1255?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","tname":"Aliens and Nationality","by":{"0":"8, 11, 8, 28, 29","1":"3, 22","2":"6"}},{"t":"usc","label":"8 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/8/1361","by":{"0":"6, 9"}},{"t":"usc","label":"8 U.S.C. § 1427","url":"https://www.law.cornell.edu/uscode/text/8/1427","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1429","url":"https://www.law.cornell.edu/uscode/text/8/1429","by":{"0":"8"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"33","1":"34"}},{"t":"reg","label":"8 C.F.R. § 103.2","url":"https://www.ecfr.gov/current/title-8/section-103.2","subs":["(b)(16)(i)"],"by":{"0":"7"}},{"t":"reg","label":"8 C.F.R. § 205.1","url":"https://www.ecfr.gov/current/title-8/section-205.1","subs":["(a)(3)(i)"],"by":{"0":"31","2":"8"}},{"t":"reg","label":"8 C.F.R. § 205.2","url":"https://www.ecfr.gov/current/title-8/section-205.2","subs":["(a)","(b)"],"by":{"0":"29, 29"}},{"t":"case","label":"ANA Int’l, Inc. v. Way","cite":"393 F.3d 886","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/393/886/","op":1,"by":{"1":"20"}},{"t":"case","label":"Abdelwahab v. Frazier","cite":"578 F.3d 817","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/578/817/","by":{"1":"20"}},{"t":"case","label":"Barton v. Barr","cite":"590 U.S. 222","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Bernardo v. Johnson","cite":"814 F.3d 481","y":2016,"url":"https://www.courtlistener.com/c/F.3d/814/481/","by":{"1":"20"}},{"t":"case","label":"Biden v. Texas","cite":"597 U.S. 785","y":2022,"id":"2021/21-954","sc":1,"op":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15, 17"}},{"t":"case","label":"Brown-Forman Distillers Corp. v. New York State Liquor Auth.","cite":"476 U.S. 573","y":1986,"id":"1985/84-2030","sc":1,"sum":"New York's Alcoholic Beverage Control Law (ABC Law) provides that a distiller, licensed to do business in the State, may not sell its products to wholesalers within the State except in accordance with a monthly price schedule previously filed with appellee State Liquor Authority, and requires that the distiller include with the schedule an affirmation that the prices in the schedule are no higher than the lowest …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"(III) Cases—Continued: Department of State v. Muñoz","cite":"144 S. Ct. 1812","y":2024,"id":"2023/23-334","sc":1,"sum":"A case in which the Court will decide whether the denial of a visa to the non-citizen spouse of a U.S. citizen infringes on a constitutionally protected interest of the citizen and, if so, whether the government properly justified that decision.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"El-Khader v. Monica","cite":"366 F.3d 562","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/366/562/","op":1,"by":{"1":"20"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Ghanem v. Upchurch","cite":"481 F.3d 222","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/481/222/","by":{"1":"20"}},{"t":"case","label":"Green v. Napolitano","cite":"627 F.3d 1341","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/627/1341/","by":{"1":"20"}},{"t":"case","label":"INS v. Miranda","cite":"459 U.S. 14","y":1982,"id":"1982/82-29","sc":1,"sum":"Regardless of whether or not even \"affirmative misconduct\" will estop the Government from enforcing the immigration laws, the evidence here did not rise to that level. Respondent showed only that the Government failed to process his application promptly. Even if the INS arguably was negligent in not acting more expeditiously, neither such conduct nor the harm to respondent was sufficient to estop the Government. Cf. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Interstate Commerce Comm’n v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"14, 15"}},{"t":"case","label":"iTech U.S., Inc. v. Renaud","cite":"5 F.4th 59","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/5/59/","by":{"1":"20"}},{"t":"case","label":"Jilin Pharm. USA, Inc. v. Chertoff","cite":"447 F.3d 196","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/447/196/","op":1,"by":{"1":"20"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"144 S. Ct. 2244","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Mehanna v. United States Citizenship & Immigration Servs.","cite":"677 F.3d 312","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/677/312/","by":{"1":"20"}},{"t":"case","label":"Nasrallah v. Barr","cite":"590 U.S. 573","y":2020,"id":"2019/18-1432","sc":1,"sum":"The Court held that the federal courts have jurisdiction to review an administrative agency’s factual findings underlying denials of withholding (and deferral) of removal relief, notwithstanding 8 U.S.C. § 1252(a)(2)(C), which seems to divest courts of jurisdiction in such cases.","sumSrc":"Oyez","by":{"1":"33, 34","2":"17"}},{"t":"case","label":"Nielsen v. Preap","cite":"586 U.S. 392","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"3"}},{"t":"case","label":"Nouritajer v. Jaddou","cite":"18 F.4th 85","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/18/85/","op":1,"by":{"1":"20"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"590 U.S. 418","y":2020,"id":"2019/17-1268","sc":1,"op":1,"sum":"The Court held that the Foreign Sovereign Immunities Act (FSIA) applies retroactively, thereby permitting recovery of punitive damages against foreign states for terrorist activities occurring prior to the passage of the current version of the statute.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Pilch v. Ashcroft","cite":"353 F.3d 585","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/353/585/","sum":"Holding that underlying nondiscretionary determinations were unreviewable.","sumSrc":"brief:1","by":{"1":"34"}},{"t":"case","label":"Polf liet v. Cuccinelli","cite":"955 F.3d 377","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/955/377/","by":{"1":"20"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"op":2,"sum":"Holding that a statute permitting the agency to terminate an employee whenever it “ `deem[s] such termination necessary or advisable in the interests of the United States' ” was discretionary.","sumSrc":"opinion","by":{"1":"17, 18, 28"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(2)","(a)(1)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"1":"4, 17, 28","2":"12"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"30"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)"],"by":{"1":"3, 2, 2"}},{"t":"usc","label":"8 U.S.C. § 1181","url":"https://www.law.cornell.edu/uscode/text/8/1181","subs":["(b)"],"stext":{"head":"§1181. Admission of immigrants into the United States","paras":[[0,"(a) Documents required; admission under quotas before June 30, 1968"],[0,"Except as provided in subsection (b) and subsection (c) no immigrant shall be admitted into the United States unless at the time of application for admission he (1) has a valid unexpired immigrant visa or was born subsequent to the issuance of such visa of the accompanying parent, and (2) presents a valid unexpired passport or other suitable travel document, or document of identity and nationality, if such document is required under the regulations issued by the Attorney General. With respect to immigrants to be admitted under quotas of quota areas prior to June 30, 1968, no immigrant visa shall be deemed valid unless the immigrant is properly chargeable to the quota area under the quota of which the visa is issued."],[0,"(b) Readmission without required documents; Attorney General's discretion"],[0,"Notwithstanding the provisions of section 1182(a)(7)(A) of this title in such cases or in such classes of cases and under such conditions as may be by regulations prescribed, returning resident immigrants, defined in section 1101(a)(27)(A) of this title, who are otherwise admissible may be readmitted to the United States by the Attorney General in his discretion without being required to obtain a passport, immigrant visa, reentry permit or other documentation."],[0,"(c) Nonapplicability to aliens admitted as refugees"],[0,"The provisions of subsection (a) shall not apply to an alien whom the Attorney General admits to the United States under section 1157 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1181?type=usc&year=mostrecent&link-type=html"},"head":"§1181. Admission of immigrants into the United States","tname":"Aliens and Nationality","by":{"1":"15","2":"19"}},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(a)"],"by":{"1":"3"}},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"1":"3"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"1":"3"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"1":"3"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"1":"3"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"1":"3"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"Bremer v. Johnson","cite":"834 F.3d 925","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/834/925/","by":{"2":"13"}},{"t":"case","label":"Department of Commerce v. New York","cite":"588 U.S. 752","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14"}},{"t":"case","label":"Fischer v. United States","cite":"144 S. Ct. 2176","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Missouri v. Jenkins","cite":"495 U.S. 33","y":1990,"id":"1989/88-1150","sc":1,"sum":"The Court held that the District Court \"abused its discretion\" by imposing a specific tax increase.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Perez v. Sturgis Public Schools","cite":"598 U.S. 142","y":2023,"id":"2022/21-887","sc":1,"sum":"An Americans with Disabilities Act lawsuit seeking compensatory damages for the denial of a free and appropriate education may proceed without exhausting the administrative processes of the Individuals with Disabilities Education Act, 20 U. S. C. §1415(l), because the remedy sought is not one IDEA provides.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"case","label":"Perez-Vargas v. Gonzales","cite":"478 F.3d 191","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/478/191/","by":{"2":"6"}},{"t":"case","label":"Sandoz, Inc. v. Amgen, Inc.","cite":"582 U.S. 1","y":2017,"id":"2016/15-1039","sc":1,"sum":"The Court determined that the Biologics Price Competition and Innovation Act of 2009 allows for commercial notice of a “biosimilar product” to be effective if given prior to approval by the Food and Drug Administration (FDA), but that the Act’s notice requirement is not enforceable with an injunction.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"United States v. X-Citement Video, Inc.","cite":"513 U.S. 64","y":1994,"id":"1994/93-723","sc":1,"sum":"The Court relied on an awkward grammatical construction as it held that the term \"knowingly\" applied to the entire passage of the law. Writing for the majority, Chief Justice William Rehnquist stated that other interpretations failed to make sense since Congress obviously did not envision people accidentally mailing underage pornographic materials.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Weyerhaeuser Co. v. United States Fish & Wildlife Service","cite":"586 U.S. 9","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14, 15"}},{"t":"usc","label":"8 U.S.C. § 1157","url":"https://www.law.cornell.edu/uscode/text/8/1157","subs":["(c)(1)"],"by":{"2":"19"}}]};